/// TOML parser error.
suberror TomlError {
  ParseError(String)
} derive(Debug)

///|
/// Parse TOML text into a deterministic JSON value.
/// Supports: comments (#), bare/dotted keys, tables, nested tables,
/// strings with escapes, integers, booleans, and arrays.
/// Raises `TomlError` on malformed input or duplicate keys.
///
pub fn parse_toml(text : String) -> Json raise TomlError {
  let root : Map[String, Json] = Map::new()
  let mut current_table_path : Array[String] = []
  for line in text.split("\n") {
    let trimmed = line.trim()
    // skip blank lines and comments
    if trimmed.is_empty() || trimmed[0] == '#' {
      continue
    }
    // table header: [key.dotted]
    if trimmed[0] == '[' {
      let rest = trimmed.sub(start=1, end=trimmed.length() - 1).to_owned().trim()
      current_table_path = parse_key_path(rest)?
      continue
    }
    // key = value
    let eq_pos = trimmed.index_of("=")
    if eq_pos < 0 {
      raise TomlError::ParseError("missing '=' in line: \{trimmed}")
    }
    let raw_key = trimmed[:eq_pos].trim()
    let raw_value = trimmed[eq_pos + 1:].trim()
    let key_path = parse_key_path(raw_key)?
    let full_path = current_table_path.clone()
    for k in key_path {
      full_path.push(k)
    }
    let value = parse_value(raw_value)?
    set_nested(root, full_path, value)?
  }
  json_from_map(root)
}

///|
/// Parse a dotted key path like "a.b.c" or just "a".
fn parse_key_path(text : String) -> Array[String] raise TomlError {
  if text.is_empty() {
    raise TomlError::ParseError("empty key")
  }
  let parts : Array[String] = text.split(".").filter(p => !p.trim().is_empty()).to_array()
  if parts.is_empty() {
    raise TomlError::ParseError("empty key path: \"\{text}\"")
  }
  let out : Array[String] = []
  for p in parts {
    let trimmed = p.trim()
    if trimmed.is_empty() {
      raise TomlError::ParseError("empty key segment in: \"\{text}\"")
    }
    // bare keys: only allow alphanumeric, _, -
    for i in 0..<trimmed.length() {
      let ch = trimmed[i]
      let ok = (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') ||
        (ch >= '0' && ch <= '9') || ch == '_' || ch == '-'
      if !ok {
        raise TomlError::ParseError("invalid character in bare key \"\{trimmed}\": '\\u\{ch.to_int().to_string_radix(16)}'")
      }
    }
    out.push(trimmed)
  }
  out
}

///|
/// Set a value at a nested path in the map, creating intermediate tables.
fn set_nested(root : Map[String, Json], path : Array[String], value : Json) -> Unit raise TomlError {
  let mut current_map = root
  for i in 0..<path.length() - 1 {
    let key = path[i]
    if current_map.contains(key) {
      match current_map[key] {
        Json::Object(inner) => current_map = inner
        _ => raise TomlError::ParseError("key \"\{key}\" is not a table")
      }
    } else {
      let new_map : Map[String, Json] = Map::new()
      current_map[key] = Json::object(new_map)
      current_map = new_map
    }
  }
  let last_key = path[path.length() - 1]
  if current_map.contains(last_key) {
    raise TomlError::ParseError("duplicate key: \"\{last_key}\"")
  }
  current_map[last_key] = value
}

///|
/// Parse a TOML value into a Json.
fn parse_value(text : String) -> Json raise TomlError {
  let t = text.trim()
  if t.is_empty() {
    raise TomlError::ParseError("empty value")
  }
  // array
  if t[0] == '[' {
    return parse_array(t)
  }
  // string (double-quoted)
  if t[0] == '"' {
    return parse_string(t)
  }
  // boolean
  if t == "true" {
    return Json::boolean(true)
  }
  if t == "false" {
    return Json::boolean(false)
  }
  // integer
  let int_val : Int? = @string.parse_int(t) catch { _ => None }
  match int_val {
    Some(n) => {
      Json::number(n.to_double(), repr=t.to_owned())
    }
    None => raise TomlError::ParseError("invalid value: \"\{t}\"")
  }
}

///|
/// Parse a TOML double-quoted string with escapes.
fn parse_string(text : String) -> Json raise TomlError {
  if text.length() < 2 || text[0] != '"' {
    raise TomlError::ParseError("invalid string: \"\{text}\"")
  }
  let mut buf = StringBuilder::new()
  let mut i = 1
  let len = text.length()
  while i < len {
    let ch = text[i]
    if ch == '"' {
      // end of string
      i += 1
      // check for trailing garbage after closing quote
      let rest = text.sub(start=i, end=len).trim()
      if !rest.is_empty() {
        raise TomlError::ParseError("trailing content after string: \"\{rest}\"")
      }
      return Json::string(buf.to_string())
    }
    if ch == '\\' {
      i += 1
      if i >= len {
        raise TomlError::ParseError("unterminated escape in string")
      }
      let escaped = text[i]
      match escaped {
        '"' => buf.write_char('"')
        '\\' => buf.write_char('\\')
        'n' => buf.write_char('\n')
        't' => buf.write_char('\t')
        _ => raise TomlError::ParseError("invalid escape: \\\{escaped}")
      }
    } else {
      buf.write_char(ch)
    }
    i += 1
  }
  raise TomlError::ParseError("unterminated string")
}

///|
/// Parse a TOML array into a Json array.
fn parse_array(text : String) -> Json raise TomlError {
  if text.is_empty() || text[0] != '[' {
    raise TomlError::ParseError("invalid array: \"\{text}\"")
  }
  let mut i = 1
  let len = text.length()
  let mut values : Array[Json] = []
  let mut current = StringBuilder::new()
  let mut depth = 0
  while i < len {
    let ch = text[i]
    if ch == '[' {
      if depth == 0 {
        // finish current simple value if any
        let seg = current.to_string().trim()
        if !seg.is_empty() {
          values.push(parse_value(seg)?)
          current = StringBuilder::new()
        }
      }
      depth += 1
      current.write_char(ch)
    } else if ch == ']' {
      if depth == 0 {
        // end of this array
        let seg = current.to_string().trim()
        if !seg.is_empty() {
          values.push(parse_value(seg)?)
        }
        i += 1
        // check trailing
        let rest = text.sub(start=i, end=len).trim()
        if !rest.is_empty() {
          raise TomlError::ParseError("trailing content after array: \"\{rest}\"")
        }
        return Json::array(values)
      }
      depth -= 1
      current.write_char(ch)
    } else if ch == ',' && depth == 0 {
      let seg = current.to_string().trim()
      if !seg.is_empty() {
        values.push(parse_value(seg)?)
      }
      current = StringBuilder::new()
    } else {
      current.write_char(ch)
    }
    i += 1
  }
  raise TomlError::ParseError("unterminated array")
}

///|
/// Convert a Map[String, Json] to a Json::Object, ensuring deterministic order.
fn json_from_map(m : Map[String, Json]) -> Json {
  Json::object(m)
}

///|
test {
  let toml = #|
    # This is a TOML document.
    title = "TOML Example"

    [owner]
    name = "Tom"
    age = 29

    [database.settings]
    host = "localhost"
    port = 5432
  |
  let json = parse_toml(toml)
  inspect(json.stringify(), ~content=
    "{\"title\":\"TOML Example\",\"owner\":{\"name\":\"Tom\",\"age\":29},\"database\":{\"settings\":{\"host\":\"localhost\",\"port\":5432}}}"
  )
}

///|
test "bare key with underscores and dashes" {
  let toml = "my-key = 42\n_underscore = -1\n"
  let json = parse_toml(toml)
  inspect(json.stringify(), ~content=
    "{\"my-key\":42,\"_underscore\":-1}"
  )
}

///|
test "boolean values" {
  let toml = "a = true\nb = false\n"
  let json = parse_toml(toml)
  inspect(json.stringify(), ~content=
    "{\"a\":true,\"b\":false}"
  )
}

///|
test "string escapes" {
  let toml = "txt = \"hello\\nworld\\ttab\\\\quote\\\"end\"\n"
  let json = parse_toml(toml)
  // The value should contain actual newline, tab, backslash, quote
  let result = json.stringify()
  inspect(result, ~content=
    "{\"txt\":\"hello\\nworld\\ttab\\\\quote\\\"end\"}"
  )
}

///|
test "array of integers" {
  let toml = "arr = [1, 2, 3]\n"
  let json = parse_toml(toml)
  inspect(json.stringify(), ~content=
    "{\"arr\":[1,2,3]}"
  )
}

///|
test "array of mixed types" {
  let toml = "arr = [1, true, \"hello\"]\n"
  let json = parse_toml(toml)
  inspect(json.stringify(), ~content=
    "{\"arr\":[1,true,\"hello\"]}"
  )
}

///|
test "dotted keys" {
  let toml = "a.b.c = \"deep\"\nx.y = 1\n"
  let json = parse_toml(toml)
  inspect(json.stringify(), ~content=
    "{\"a\":{\"b\":{\"c\":\"deep\"}},\"x\":{\"y\":1}}"
  )
}

///|
test "duplicate key error" {
  let toml = "key = 1\nkey = 2\n"
  try parse_toml(toml) catch {
    TomlError::ParseError(msg) => assert_true(msg.contains("duplicate"))
  } noraise {
    _ => fail("expected duplicate key error")
  }
}

///|
test "malformed input - missing value" {
  let toml = "key =\n"
  try parse_toml(toml) catch {
    TomlError::ParseError(_) => ()
  } noraise {
    _ => fail("expected error")
  }
}

///|
test "malformed input - invalid escape" {
  let toml = "x = \"hello\\z\"\n"
  try parse_toml(toml) catch {
    TomlError::ParseError(_) => ()
  } noraise {
    _ => fail("expected error")
  }
}

///|
test "empty document" {
  let toml = ""
  let json = parse_toml(toml)
  inspect(json.stringify(), ~content="{}")
}

///|
test "only comments" {
  let toml = "# just a comment\n  # another\n"
  let json = parse_toml(toml)
  inspect(json.stringify(), ~content="{}")
}
"}

{"path": "/private/tmp/prompt_demos/runs_flash-demos-plus/workspaces/02/cmd/tomljson/main.mbt", "content": "///|
/// tomljson — Convert TOML to JSON.
///
async fn main {
  let matches = @argparse.parse(
    Command(
      "tomljson",
      about="Convert TOML to JSON.",
      flags=[
        FlagArg("stdin", long="stdin", about="Read TOML from stdin."),
      ],
      positionals=[
        PositionArg("input", default_values=["-"], about="TOML file path."),
      ],
    ),
  )
  let use_stdin = match matches.flags.get("stdin") {
    Some(true) => true
    _ => false
  }
  let input = if use_stdin {
    @stdio.stdin.read_all().text()
  } else {
    let path = match matches.values.get("input") {
      Some([p, ..]) => p
      _ => fail("missing parsed argument: input")
    }
    @fs.read_file(path).text() catch {
      error => {
        @stdio.stderr.write("error: cannot read file: \{path}\n")
        @sys.exit(1)
        return
      }
    }
  }
  match @toml.parse_toml(input) {
    Ok(json) => println(json.stringify())
    Err(TomlError::ParseError(msg)) => {
      @stdio.stderr.write("error: \{msg}\n")
      @sys.exit(1)
    }
  }
}
"}

