    }
  }
  -1
}

///|
/// Parse a dotted key path like "a.b.c" or just "a".
fn parse_key_path(text : String) -> Array[String] raise TomlError {
  if text.is_empty() {
    raise TomlError::ParseError("empty key")
  }
  let parts = text.split(".")
    .filter(fn(p) { !p.trim().to_owned().is_empty() })
    .to_array()
  if parts.is_empty() {
    raise TomlError::ParseError("empty key path: \"\{text}\"")
  }
  let out : Array[String] = []
  for p_view in parts {
    let trimmed = p_view.trim().to_owned()
    if trimmed.is_empty() {
      raise TomlError::ParseError("empty key segment in: \"\{text}\"")
    }
    // bare keys: only allow alphanumeric, _, -
    for i in 0..<trimmed.length() {
      let ch = trimmed[i]
      let ok = (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') ||
        (ch >= '0' && ch <= '9') || ch == '_' || ch == '-'
      if !ok {
        let hex = ch.to_int().to_string_radix(16)
        raise TomlError::ParseError("invalid character in bare key \"\{trimmed}\": '\\u\{hex}'")
      }
    }
    out.push(trimmed)
  }
  out
}

///|
/// Set a value at a nested path in the map, creating intermediate tables.
fn set_nested(root : Map[String, Json], path : Array[String], value : Json) -> Unit raise TomlError {
  let mut current_map = root
  for i in 0..<path.length() - 1 {
    let key = path[i]
    if current_map.contains(key) {
      match current_map[key] {
        Json::Object(inner) => current_map = inner
        _ => raise TomlError::ParseError("key \"\{key}\" is not a table")
      }
    } else {
      let new_map : Map[String, Json] = Map::new()
      current_map[key] = Json::object(new_map)
      current_map = new_map
    }
  }
  let last_key = path[path.length() - 1]
  if current_map.contains(last_key) {
    raise TomlError::ParseError("duplicate key: \"\{last_key}\"")
  }
  current_map[last_key] = value
}

///|
/// Parse a TOML value into a Json.
fn parse_value(text : String) -> Json raise TomlError {
  let t = text.trim()
  if t.is_empty() {
    raise TomlError::ParseError("empty value")
  }
  // array
  if t[0] == '[' {
    return parse_array(t)
  }
  // string (double-quoted)
  if t[0] == '"' {
    return parse_string(t)
  }
  // boolean
  if t == "true" {
    return Json::boolean(true)
  }
  if t == "false" {
    return Json::boolean(false)
  }
  // integer - try to parse as Int
  let int_val : Int? = @string.parse_int(t) catch { _ => None }
  match int_val {
    Some(n) => {
      Json::number(n.to_double(), repr=t.to_owned())
    }
    None => raise TomlError::ParseError("invalid value: \"\{t}\"")
  }
}

///|
/// Parse a TOML double-quoted string with escapes.
fn parse_string(text : String) -> Json raise TomlError {
  if text.length() < 2 || text[0] != '"' {
    raise TomlError::ParseError("invalid string: \"\{text}\"")
  }
  let mut buf = StringBuilder::new()
  let mut i = 1
  let len = text.length()
  while i < len {
    let ch = text[i]
    if ch == '"' {
      // end of string
      i += 1
      // check for trailing garbage after closing quote
      let rest = text.sub(start=i, end=len).to_owned().trim()
      if !rest.is_empty() {
        raise TomlError::ParseError("trailing content after string: \"\{rest}\"")
      }
      return Json::string(buf.to_string())
    }
    if ch == '\\' {
      i += 1
      if i >= len {
        raise TomlError::ParseError("unterminated escape in string")
      }
      let escaped = text[i]
      match escaped {
        '"' => buf.write_char('"')
        '\\' => buf.write_char('\\')
        'n' => buf.write_char('\n')
        't' => buf.write_char('\t')
        _ => raise TomlError::ParseError("invalid escape: \\\{escaped}")
      }
    } else {
      buf.write_char(ch)
    }
    i += 1
  }
  raise TomlError::ParseError("unterminated string")
}

///|
/// Parse a TOML array into a Json array.
fn parse_array(text : String) -> Json raise TomlError {
  if text.is_empty() || text[0] != '[' {
    raise TomlError::ParseError("invalid array: \"\{text}\"")
  }
  let mut i = 1
  let len = text.length()
  let mut values : Array[Json] = []
  let mut current = StringBuilder::new()
  let mut depth = 0
  while i < len {
    let ch = text[i]
    if ch == '[' {
      if depth == 0 {
        // finish current simple value if any
        let seg = current.to_string().trim()
        if !seg.is_empty() {
          values.push(parse_value(seg))
          current = StringBuilder::new()
        }
      }
      depth += 1
      current.write_char(ch)
    } else if ch == ']' {
      if depth == 0 {
        // end of this array
        let seg = current.to_string().trim()
        if !seg.is_empty() {
          values.push(parse_value(seg))
        }
        i += 1
        // check trailing
        let rest = text.sub(start=i, end=len).to_owned().trim()
        if !rest.is_empty() {
          raise TomlError::ParseError("trailing content after array: \"\{rest}\"")
        }
        return Json::array(values)
      }
      depth -= 1
      current.write_char(ch)
    } else if ch == ',' && depth == 0 {
      let seg = current.to_string().trim()
      if !seg.is_empty() {
        values.push(parse_value(seg))
      }
      current = StringBuilder::new()
    } else {
      current.write_char(ch)
    }
    i += 1
  }
  raise TomlError::ParseError("unterminated array")
}

///|
/// Convert a Map[String, Json] to a Json::Object, ensuring deterministic order.
fn json_from_map(m : Map[String, Json]) -> Json {
  Json::object(m)
}

