fn parse_string(text : String) -> Json raise TomlError {
  if text.length() < 2 || first_char(text) != '"' {
    raise TomlError::ParseError("invalid string: \"\{text}\"")
  }
  let buf = StringBuilder::new()
  let mut i = 1
  let len = text.length()
  while i < len {
    match text.get_char(i) {
      Some(ch) if ch == '"' => {
        // end of string
        i += 1
        // check for trailing garbage after closing quote
        let rest = text.sub(start=i, end=len).to_owned().trim().to_owned()
        if !rest.is_empty() {
          raise TomlError::ParseError("trailing content after string: \"\{rest}\"")
        }
        return Json::string(buf.to_string())
      }
      Some(ch) if ch == '\\' => {
        i += 1
        if i >= len {
          raise TomlError::ParseError("unterminated escape in string")
        }
        match text.get_char(i) {
          Some('"') => buf.write_char('"')
          Some('\\') => buf.write_char('\\')
          Some('n') => buf.write_char('\n')
          Some('t') => buf.write_char('\t')
          Some(esc) => raise TomlError::ParseError("invalid escape: \\\{esc}")
          None => raise TomlError::ParseError("unterminated escape in string")
        }
      }
      Some(ch) => buf.write_char(ch)
      None => raise TomlError::ParseError("unterminated string")
    }
    i += 1
  }
  raise TomlError::ParseError("unterminated string")
}

///|
/// Parse a TOML array into a Json array.
fn parse_array(text : String) -> Json raise TomlError {
  if text.is_empty() || first_char(text) != '[' {
    raise TomlError::ParseError("invalid array: \"\{text}\"")
  }
  let mut i = 1
  let len = text.length()
  let mut values : Array[Json] = []
  let mut current = StringBuilder::new()
  let mut depth = 0
  while i < len {
    match text.get_char(i) {
      Some('[') => {
        if depth == 0 {
          // finish current simple value if any
          let seg = current.to_string().trim().to_owned()
          if !seg.is_empty() {
            values.push(parse_value(seg))
            current = StringBuilder::new()
          }
        }
        depth += 1
        current.write_char('[')
      }
      Some(']') if depth == 0 => {
        // end of this array
        let seg = current.to_string().trim().to_owned()
        if !seg.is_empty() {
          values.push(parse_value(seg))
        }
        i += 1
        // check trailing
        let rest = text.sub(start=i, end=len).to_owned().trim().to_owned()
        if !rest.is_empty() {
          raise TomlError::ParseError("trailing content after array: \"\{rest}\"")
        }
        return Json::array(values)
      }
      Some(']') => {
        depth -= 1
        current.write_char(']')
      }
      Some(',') if depth == 0 => {
        let seg = current.to_string().trim().to_owned()
        if !seg.is_empty() {
          values.push(parse_value(seg))
        }
        current = StringBuilder::new()
      }
      Some(c) => current.write_char(c)
      None => raise TomlError::ParseError("unterminated array")
    }
    i += 1
  }
  raise TomlError::ParseError("unterminated array")
}

///|
/// Convert a Map[String, Json] to a Json::Object, ensuring deterministic order.
fn json_from_map(m : Map[String, Json]) -> Json {
  Json::object(m)
}
