///|
/// TOML parser error.
suberror TomlError {
  ParseError(String)
} derive(Debug)

///|
/// Parse TOML text into a deterministic JSON value.
/// Supports: comments (#), bare/dotted keys, tables, nested tables,
/// strings with escapes, integers, booleans, and arrays.
/// Raises `TomlError` on malformed input or duplicate keys.
///
pub fn parse_toml(text : String) -> Json raise TomlError {
  let root : Map[String, Json] = Map([], capacity=0)
  let mut current_table_path : Array[String] = []
  for line_view in text.split("\n") {
    let trimmed_sv = line_view.trim()
    let trimmed = trimmed_sv.to_owned()
    // skip blank lines and comments
    if trimmed.is_empty() || first_char(trimmed) == '#' {
      continue
    }
    // table header: [key.dotted]
    if first_char(trimmed) == '[' {
      let inner = trimmed.sub(start=1, end=trimmed.length() - 1)
      let rest = inner.to_owned().trim().to_owned()
      current_table_path = parse_key_path(rest)
      continue
    }
    // key = value
    let eq_pos = find_char_pos(trimmed, '=')
    if eq_pos < 0 {
      raise TomlError::ParseError("missing '=' in line: \{trimmed}")
    }
    let raw_key = trimmed[:eq_pos].to_owned().trim().to_owned()
    let raw_value = trimmed[eq_pos + 1:].to_owned().trim().to_owned()
    let key_path = parse_key_path(raw_key)
    let full_path = current_table_path.copy()
    for k in key_path {
      full_path.push(k)
    }
    let value = parse_value(raw_value)
    set_nested(root, full_path, value)
  }
  json_from_map(root)
}

///|
/// Return the first character of a string, or space if empty.
fn first_char(s : String) -> Char {
  match s.get_char(0) {
    Some(c) => c
    None => ' '
  }
}

///|
/// Find first occurrence of a character in a string, return index or -1.
fn find_char_pos(s : String, ch : Char) -> Int {
  let mut i = 0
  let len = s.length()
  while i < len {
    match s.get_char(i) {
      Some(c) if c == ch => return i
      _ => i += 1
    }
  }
  -1
}

///|
/// Parse a dotted key path like "a.b.c" or just "a".
fn parse_key_path(text : String) -> Array[String] raise TomlError {
  if text.is_empty() {
    raise TomlError::ParseError("empty key")
  }
  let parts = text
    .split(".")
    .filter(fn(p) { !p.trim().to_owned().is_empty() })
    .to_array()
  if parts.is_empty() {
    raise TomlError::ParseError("empty key path: \"\{text}\"")
  }
  let out : Array[String] = []
  for p_view in parts {
    let trimmed = p_view.trim().to_owned()
    if trimmed.is_empty() {
      raise TomlError::ParseError("empty key segment in: \"\{text}\"")
    }
    // bare keys: only allow alphanumeric, _, -
    let mut i = 0
    let len = trimmed.length()
    while i < len {
      match trimmed.get_char(i) {
        Some(c) => {
          let ok = (c >= 'a' && c <= 'z') ||
            (c >= 'A' && c <= 'Z') ||
            (c >= '0' && c <= '9') ||
            c == '_' ||
            c == '-'
          if !ok {
            raise TomlError::ParseError(
              "invalid character in bare key \"\{trimmed}\"",
            )
          }
        }
        None => ()
      }
      i += 1
    }
    out.push(trimmed)
  }
  out
}

///|
/// Set a value at a nested path in the map, creating intermediate tables.
fn set_nested(
  root : Map[String, Json],
  path : Array[String],
  value : Json,
) -> Unit raise TomlError {
  let mut current_map = root
  let mut i = 0
  let path_len = path.length()
  while i < path_len - 1 {
    let key = path[i]
    if current_map.contains(key) {
      match current_map[key] {
        Json::Object(inner) => current_map = inner
        _ => raise TomlError::ParseError("key \"\{key}\" is not a table")
      }
    } else {
      let new_map : Map[String, Json] = Map([], capacity=0)
      current_map[key] = Json::object(new_map)
      current_map = new_map
    }
    i += 1
  }
  let last_key = path[path_len - 1]
  if current_map.contains(last_key) {
    raise TomlError::ParseError("duplicate key: \"\{last_key}\"")
  }
  current_map[last_key] = value
}

///|
/// Parse a TOML value into a Json.
fn parse_value(text : String) -> Json raise TomlError {
  if text.is_empty() {
    raise TomlError::ParseError("empty value")
  }
  // array
  if first_char(text) == '[' {
    return parse_array(text)
  }
  // string (double-quoted)
  if first_char(text) == '"' {
    return parse_string(text)
  }
  // boolean
  if text == "true" {
    return Json::boolean(true)
  }
  if text == "false" {
    return Json::boolean(false)
  }
  // integer
  let int_val = @string.parse_int(text) catch {
    _ => raise TomlError::ParseError("invalid value: \"\{text}\"")
  }
  Json::number(int_val.to_double(), repr=text)
}

///|
/// Parse a TOML double-quoted string with escapes.
fn parse_string(text : String) -> Json raise TomlError {
  if text.length() < 2 || first_char(text) != '"' {
    raise TomlError::ParseError("invalid string: \"\{text}\"")
  }
  let buf = StringBuilder::new()
  let mut i = 1
  let len = text.length()
  while i < len {
    match text.get_char(i) {
      Some(ch) if ch == '"' => {
        // end of string
        i += 1
        // check for trailing garbage after closing quote
        let rest = text.sub(start=i, end=len).to_owned().trim().to_owned()
        if !rest.is_empty() {
          raise TomlError::ParseError(
            "trailing content after string: \"\{rest}\"",
          )
        }
        return Json::string(buf.to_string())
      }
      Some(ch) if ch == '\\' => {
        i += 1
        if i >= len {
          raise TomlError::ParseError("unterminated escape in string")
        }
        match text.get_char(i) {
          Some('"') => buf.write_char('"')
          Some('\\') => buf.write_char('\\')
          Some('n') => buf.write_char('\n')
          Some('t') => buf.write_char('\t')
          Some(esc) => raise TomlError::ParseError("invalid escape: \\\{esc}")
          None => raise TomlError::ParseError("unterminated escape in string")
        }
      }
      Some(ch) => buf.write_char(ch)
      None => raise TomlError::ParseError("unterminated string")
    }
    i += 1
  }
  raise TomlError::ParseError("unterminated string")
}

///|
/// Parse a TOML array into a Json array.
fn parse_array(text : String) -> Json raise TomlError {
  if text.is_empty() || first_char(text) != '[' {
    raise TomlError::ParseError("invalid array: \"\{text}\"")
  }
  let mut i = 1
  let len = text.length()
  let values : Array[Json] = []
  let mut current = StringBuilder::new()
  let mut depth = 0
  while i < len {
    match text.get_char(i) {
      Some('[') => {
        if depth == 0 {
          // finish current simple value if any
          let seg = current.to_string().trim().to_owned()
          if !seg.is_empty() {
            values.push(parse_value(seg))
            current = StringBuilder::new()
          }
        }
        depth += 1
        current.write_char('[')
      }
      Some(']') if depth == 0 => {
        // end of this array
        let seg = current.to_string().trim().to_owned()
        if !seg.is_empty() {
          values.push(parse_value(seg))
        }
        i += 1
        // check trailing
        let rest = text.sub(start=i, end=len).to_owned().trim().to_owned()
        if !rest.is_empty() {
          raise TomlError::ParseError(
            "trailing content after array: \"\{rest}\"",
          )
        }
        return Json::array(values)
      }
      Some(']') => {
        depth -= 1
        current.write_char(']')
      }
      Some(',') if depth == 0 => {
        let seg = current.to_string().trim().to_owned()
        if !seg.is_empty() {
          values.push(parse_value(seg))
        }
        current = StringBuilder::new()
      }
      Some(c) => current.write_char(c)
      None => raise TomlError::ParseError("unterminated array")
    }
    i += 1
  }
  raise TomlError::ParseError("unterminated array")
}

///|
/// Convert a Map[String, Json] to a Json::Object, ensuring deterministic order.
fn json_from_map(m : Map[String, Json]) -> Json {
  Json::object(m)
}

