///|
/// tomljson — Convert TOML to JSON.
///
async fn main {
  let matches = @argparse.parse(
    Command(
      "tomljson",
      about="Convert TOML to JSON.",
      flags=[FlagArg("stdin", long="stdin", about="Read TOML from stdin.")],
      positionals=[
        PositionArg("input", default_values=["-"], about="TOML file path."),
      ],
    ),
  )
  let use_stdin = match matches.flags.get("stdin") {
    Some(true) => true
    _ => false
  }
  let input = if use_stdin {
    @stdio.stdin.read_all().text()
  } else {
    let path = match matches.values.get("input") {
      Some([p, ..]) => p
      _ => fail("missing parsed argument: input")
    }
    @fs.read_file(path).text() catch {
      _ => {
        @stdio.stderr.write("error: cannot read file: \{path}\n")
        @sys.exit(1)
        ""
      }
    }
  }
  let json = @toml.parse_toml(input) catch {
    error => {
      @stdio.stderr.write("error: \{error.to_repr()}\n")
      @sys.exit(1)
      Json::null()
    }
  }
  println(json.stringify())
}
